import{_ as l,a0 as o,w as h,s as d,ao as t,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"在 Ubuntu 中安裝 Apache、MySQL、PHP（LAMP）套件 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 中安裝 Apache、MySQL、PHP（LAMP）套件 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 中安裝 Apache、MySQL、PHP（LAMP）套件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 中安裝 Apache、MySQL、PHP（LAMP）套件 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20190205 Install Apache, MySQL, PHP (LAMP) Stack On Ubuntu 18.04 LTS","title":"在 Ubuntu 中安裝 Apache、MySQL、PHP（LAMP）套件","tag":"202101","desc":""},"relativePath":"202101/20190205 Install Apache, MySQL, PHP (LAMP) Stack On Ubuntu 18.04 LTS.md","filePath":"[post].md"}'),c={name:"202101/20190205 Install Apache, MySQL, PHP (LAMP) Stack On Ubuntu 18.04 LTS.md"};function r(g,s,u,k,b,y){const n=o("Link");return h(),d("div",null,[s[23]||(s[23]=t(`<h1 id="在-ubuntu-中安裝-apache、mysql、php-lamp-套件" tabindex="-1">在 Ubuntu 中安裝 Apache、MySQL、PHP（LAMP）套件 <a class="header-anchor" href="#在-ubuntu-中安裝-apache、mysql、php-lamp-套件" aria-label="Permalink to “在 Ubuntu 中安裝 Apache、MySQL、PHP（LAMP）套件”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/02/lamp-720x340.jpg" alt=""></p><p><strong>LAMP</strong> 套件是一種流行的開源 Web 開發平台，可用於運行和部署動態網站和基於 Web 的應用程序。通常，LAMP 套件由 Apache Web 服務器、MariaDB/MySQL 資料庫、PHP/Python/Perl 程序設計（腳本）語言組成。 LAMP 是 <strong>L</strong>inux，<strong>M</strong>ariaDB/<strong>M</strong>YSQL，<strong>P</strong>HP/<strong>P</strong>ython/<strong>P</strong>erl 的縮寫。 本教程描述瞭如何在 Ubuntu 18.04 LTS 服務器中安裝 Apache、MySQL、PHP（LAMP 套件）。</p><p>就本教程而言，我們將使用以下 Ubuntu 測試。</p><ul><li><strong>操作系統</strong>：Ubuntu 18.04.1 LTS Server Edition</li><li><strong>IP 地址</strong> ：192.168.225.22/24</li></ul><h3 id="_1-安裝-apache-web-服務器" tabindex="-1">1. 安裝 Apache Web 服務器 <a class="header-anchor" href="#_1-安裝-apache-web-服務器" aria-label="Permalink to “1. 安裝 Apache Web 服務器”">​</a></h3><p>首先，利用下面命令更新 Ubuntu 服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt upgrade</span></span></code></pre></div><p>然後，安裝 Apache Web 服務器（命令如下）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install apache2</span></span></code></pre></div><p>檢查 Apache Web 服務器是否已經運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status apache2</span></span></code></pre></div><p>輸出結果大概是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>● apache2.service - The Apache HTTP Server</span></span>
<span class="line"><span> Loaded: loaded (/lib/systemd/system/apache2.service; enabled; vendor preset: en</span></span>
<span class="line"><span> Drop-In: /lib/systemd/system/apache2.service.d</span></span>
<span class="line"><span> └─apache2-systemd.conf</span></span>
<span class="line"><span> Active: active (running) since Tue 2019-02-05 10:48:03 UTC; 1min 5s ago</span></span>
<span class="line"><span> Main PID: 2025 (apache2)</span></span>
<span class="line"><span> Tasks: 55 (limit: 2320)</span></span>
<span class="line"><span> CGroup: /system.slice/apache2.service</span></span>
<span class="line"><span> ├─2025 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span> ├─2027 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span> └─2028 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Feb 05 10:48:02 ubuntuserver systemd[1]: Starting The Apache HTTP Server...</span></span>
<span class="line"><span>Feb 05 10:48:03 ubuntuserver apachectl[2003]: AH00558: apache2: Could not reliably</span></span>
<span class="line"><span>Feb 05 10:48:03 ubuntuserver systemd[1]: Started The Apache HTTP Server.</span></span></code></pre></div><p>祝賀你！ Apache 服務已經啓動並運行了！！</p><h4 id="_1-1-調整防火牆允許-apache-web-服務器" tabindex="-1">1.1 調整防火牆允許 Apache Web 服務器 <a class="header-anchor" href="#_1-1-調整防火牆允許-apache-web-服務器" aria-label="Permalink to “1.1 調整防火牆允許 Apache Web 服務器”">​</a></h4><p>默認情況下，如果你已在 Ubuntu 中啓用 UFW 防火牆，則無法從遠程系統訪問 Apache Web 服務器。 必須按照以下步驟開啓 <code>http</code> 和 <code>https</code> 端口。</p><p>首先，使用以下命令列出 Ubuntu 系統上可用的應用程序配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ufw app list</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Available applications:</span></span>
<span class="line"><span>Apache</span></span>
<span class="line"><span>Apache Full</span></span>
<span class="line"><span>Apache Secure</span></span>
<span class="line"><span>OpenSSH</span></span></code></pre></div><p>如你所見，Apache 和 OpenSSH 應用程序已安裝 UFW 配置文件。你可以使用 <code>ufw app info &quot;Profile Name&quot;</code> 命令列出有關每個配置文件及其包含的規則的信息。</p><p>讓我們研究一下 “Apache Full” 配置文件。 為此，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ufw app info &quot;Apache Full&quot;</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Profile: Apache Full</span></span>
<span class="line"><span>Title: Web Server (HTTP,HTTPS)</span></span>
<span class="line"><span>Description: Apache v2 is the next generation of the omnipresent Apache web</span></span>
<span class="line"><span>server.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Ports:</span></span>
<span class="line"><span>80,443/tcp</span></span></code></pre></div><p>如你所見，“Apache Full” 配置文件包含了啓用經由端口 <strong>80</strong> 和 <strong>443</strong> 的傳輸規則：</p><p>現在，運行以下命令配置允許 HTTP 和 HTTPS 傳入通信：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ufw allow in &quot;Apache Full&quot;</span></span>
<span class="line"><span>Rules updated</span></span>
<span class="line"><span>Rules updated (v6)</span></span></code></pre></div><p>如果你不想允許 HTTP 通信，而只允許 HTTP（80） 通信，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ufw app info &quot;Apache&quot;</span></span></code></pre></div><h4 id="_1-2-測試-apache-web-服務器" tabindex="-1">1.2 測試 Apache Web 服務器 <a class="header-anchor" href="#_1-2-測試-apache-web-服務器" aria-label="Permalink to “1.2 測試 Apache Web 服務器”">​</a></h4>`,32)),p("p",null,[s[2]||(s[2]=a("現在，打開 Web 瀏覽器並導航到 ",-1)),e(n,{href:"http://localhost/"},{default:i(()=>[...s[0]||(s[0]=[a("http://localhost/",-1)])]),_:1}),s[3]||(s[3]=a(" 或 ",-1)),e(n,{href:"http://IP-Address/"},{default:i(()=>[...s[1]||(s[1]=[a("http://IP-Address/",-1)])]),_:1}),s[4]||(s[4]=a(" 來訪問 Apache 測試頁。",-1))]),s[24]||(s[24]=t(`<p><img src="https://www.ostechnix.com/wp-content/uploads/2016/06/apache-2.png" alt=""></p><p>如果看到上面類似的顯示內容，那就成功了。 Apache 服務器正在工作！</p><h3 id="_2-安裝-mysql" tabindex="-1">2. 安裝 MySQL <a class="header-anchor" href="#_2-安裝-mysql" aria-label="Permalink to “2. 安裝 MySQL”">​</a></h3><p>在 Ubuntu 安裝 MySQL 請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install mysql-server</span></span></code></pre></div><p>使用以下命令驗證 MySQL 服務是否正在運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status mysql</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>● mysql.service - MySQL Community Server</span></span>
<span class="line"><span>Loaded: loaded (/lib/systemd/system/mysql.service; enabled; vendor preset: enab</span></span>
<span class="line"><span>Active: active (running) since Tue 2019-02-05 11:07:50 UTC; 17s ago</span></span>
<span class="line"><span>Main PID: 3423 (mysqld)</span></span>
<span class="line"><span>Tasks: 27 (limit: 2320)</span></span>
<span class="line"><span>CGroup: /system.slice/mysql.service</span></span>
<span class="line"><span>└─3423 /usr/sbin/mysqld --daemonize --pid-file=/run/mysqld/mysqld.pid</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Feb 05 11:07:49 ubuntuserver systemd[1]: Starting MySQL Community Server...</span></span>
<span class="line"><span>Feb 05 11:07:50 ubuntuserver systemd[1]: Started MySQL Community Server.</span></span></code></pre></div><p>MySQL 正在運行！</p><h4 id="_2-1-配置資料庫管理用户-root-密碼" tabindex="-1">2.1 配置資料庫管理用户（root）密碼 <a class="header-anchor" href="#_2-1-配置資料庫管理用户-root-密碼" aria-label="Permalink to “2.1 配置資料庫管理用户（root）密碼”">​</a></h4><p>默認情況下，MySQL root 用户密碼為空。你需要通過運行以下腳本使你的 MySQL 服務器安全：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mysql_secure_installation</span></span></code></pre></div><p>系統將詢問你是否要安裝 “VALIDATE PASSWORD plugin（密碼驗證插件）”。該插件允許用户為資料庫配置強密碼憑據。如果啓用，它將自動檢查密碼的強度並強制用户設置足夠安全的密碼。<strong>禁用此插件是安全的</strong>。但是，必須為資料庫使用唯一的強密碼憑據。如果不想啓用此插件，只需按任意鍵即可跳過密碼驗證部分，然後繼續其餘步驟。</p><p>如果回答是 <code>y</code>，則會要求你選擇密碼驗證級別。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Securing the MySQL server deployment.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Connecting to MySQL using a blank password.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>VALIDATE PASSWORD PLUGIN can be used to test passwords</span></span>
<span class="line"><span>and improve security. It checks the strength of password</span></span>
<span class="line"><span>and allows the users to set only those passwords which are</span></span>
<span class="line"><span>secure enough. Would you like to setup VALIDATE PASSWORD plugin?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Press y|Y for Yes, any other key for No y</span></span></code></pre></div><p>可用的密碼驗證有 “low（低）”、 “medium（中）” 和 “strong（強）”。只需輸入適當的數字（0 表示低，1 表示中，2 表示強密碼）並按回車鍵。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>There are three levels of password validation policy:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>LOW Length &gt;= 8</span></span>
<span class="line"><span>MEDIUM Length &gt;= 8, numeric, mixed case, and special characters</span></span>
<span class="line"><span>STRONG Length &gt;= 8, numeric, mixed case, special characters and dictionary file</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please enter 0 = LOW, 1 = MEDIUM and 2 = STRONG:</span></span></code></pre></div><p>現在，輸入 MySQL root 用户的密碼。請注意，必須根據上一步中選擇的密碼策略，為 MySQL root 用户使用密碼。如果你未啓用該插件，則只需使用你選擇的任意強度且唯一的密碼即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please set the password for root here.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>New password:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Re-enter new password:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Estimated strength of the password: 50</span></span>
<span class="line"><span>Do you wish to continue with the password provided?(Press y|Y for Yes, any other key for No) : y</span></span></code></pre></div><p>兩次輸入密碼後，你將看到密碼強度（在此示例情況下為 50）。如果你確定可以，請按 <code>y</code> 繼續提供的密碼。如果對密碼長度不滿意，請按其他任意鍵並設置一個強密碼。我現在的密碼可以，所以我選擇了<code>y</code>。</p><p>對於其餘的問題，只需鍵入 <code>y</code> 並按回車鍵。這將刪除匿名用户、禁止 root 用户遠程登錄並刪除 <code>test</code>（測試）資料庫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Remove anonymous users? (Press y|Y for Yes, any other key for No) : y</span></span>
<span class="line"><span>Success.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Normally, root should only be allowed to connect from</span></span>
<span class="line"><span>&#39;localhost&#39;. This ensures that someone cannot guess at</span></span>
<span class="line"><span>the root password from the network.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Disallow root login remotely? (Press y|Y for Yes, any other key for No) : y</span></span>
<span class="line"><span>Success.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>By default, MySQL comes with a database named &#39;test&#39; that</span></span>
<span class="line"><span>anyone can access. This is also intended only for testing,</span></span>
<span class="line"><span>and should be removed before moving into a production</span></span>
<span class="line"><span>environment.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Remove test database and access to it? (Press y|Y for Yes, any other key for No) : y</span></span>
<span class="line"><span>- Dropping test database...</span></span>
<span class="line"><span>Success.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Removing privileges on test database...</span></span>
<span class="line"><span>Success.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reloading the privilege tables will ensure that all changes</span></span>
<span class="line"><span>made so far will take effect immediately.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reload privilege tables now? (Press y|Y for Yes, any other key for No) : y</span></span>
<span class="line"><span>Success.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>All done!</span></span></code></pre></div><p>以上就是為 MySQL root 用户設置密碼。</p><h4 id="_2-2-更改-mysql-超級用户的身份驗證方法" tabindex="-1">2.2 更改 MySQL 超級用户的身份驗證方法 <a class="header-anchor" href="#_2-2-更改-mysql-超級用户的身份驗證方法" aria-label="Permalink to “2.2 更改 MySQL 超級用户的身份驗證方法”">​</a></h4><p>默認情況下，Ubuntu 系統的 MySQL root 用户為 MySQL 5.7 版本及更新的版本使用插件 <code>auth_socket</code> 設置身份驗證。儘管它增強了安全性，但是當你使用任何外部程序（例如 phpMyAdmin）訪問資料庫服務器時，也會變得更困難。要解決此問題，你需要將身份驗證方法從 <code>auth_socket</code> 更改為 <code>mysql_native_password</code>。為此，請使用以下命令登錄到你的 MySQL 提示符下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mysql</span></span></code></pre></div><p>在 MySQL 提示符下運行以下命令，找到所有 MySQL 當前用户帳户的身份驗證方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SELECT user,authentication_string,plugin,host FROM mysql.user;</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+------------------|-------------------------------------------|-----------------------|-----------+</span></span>
<span class="line"><span>| user | authentication_string | plugin | host |</span></span>
<span class="line"><span>+------------------|-------------------------------------------|-----------------------|-----------+</span></span>
<span class="line"><span>| root | | auth_socket | localhost |</span></span>
<span class="line"><span>| mysql.session | *THISISNOTAVALIDPASSWORDTHATCANBEUSEDHERE | mysql_native_password | localhost |</span></span>
<span class="line"><span>| mysql.sys | *THISISNOTAVALIDPASSWORDTHATCANBEUSEDHERE | mysql_native_password | localhost |</span></span>
<span class="line"><span>| debian-sys-maint | *F126737722832701DD3979741508F05FA71E5BA0 | mysql_native_password | localhost |</span></span>
<span class="line"><span>+------------------|-------------------------------------------|-----------------------|-----------+</span></span>
<span class="line"><span>4 rows in set (0.00 sec)</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2019/02/mysql-1.png" alt=""></p><p>如你所見，Mysql root 用户使用 <code>auth_socket</code> 插件進行身份驗證。</p><p>要將此身份驗證更改為 <code>mysql_native_password</code> 方法，請在 MySQL 提示符下運行以下命令。 別忘了用你選擇的強大唯一的密碼替換 <code>password</code>。 如果已啓用 VALIDATION 插件，請確保已根據當前策略要求使用了強密碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER USER &#39;root&#39;@&#39;localhost&#39; IDENTIFIED WITH mysql_native_password BY &#39;password&#39;;</span></span></code></pre></div><p>使用以下命令更新資料庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FLUSH PRIVILEGES;</span></span></code></pre></div><p>使用命令再次檢查身份驗證方法是否已更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SELECT user,authentication_string,plugin,host FROM mysql.user;</span></span></code></pre></div><p>輸出結果：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2019/02/mysql-2.png" alt=""></p><p>好！MySQL root 用户就可以使用密碼進行身份驗證來訪問 <code>mysql shell</code>。</p><p>從 MySQL 提示符下退出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span></code></pre></div><h3 id="_3-安裝-php" tabindex="-1">3. 安裝 PHP <a class="header-anchor" href="#_3-安裝-php" aria-label="Permalink to “3. 安裝 PHP”">​</a></h3><p>安裝 PHP 請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install php libapache2-mod-php php-mysql</span></span></code></pre></div><p>安裝 PHP 後，在 Apache 文檔根目錄中創建 <code>info.php</code> 文件。通常，在大多數基於 Debian 的 Linux 發行版中，Apache 文檔根目錄為 <code>/var/www/html/</code> 或 <code>/var/www/</code>。Ubuntu 18.04 LTS 系統下，文檔根目錄是 <code>/var/www/html/</code>。</p><p>在 Apache 根目錄中創建 <code>info.php</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /var/www/html/info.php</span></span></code></pre></div><p>在此文件中編輯如下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php</span></span>
<span class="line"><span>phpinfo();</span></span>
<span class="line"><span>?&gt;</span></span></code></pre></div><p>然後按下 <code>ESC</code> 鍵並且輸入 <code>:wq</code> 保存並退出此文件。重新啓動 Apache 服務使更改生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart apache2</span></span></code></pre></div><h4 id="_3-1-測試-php" tabindex="-1">3.1 測試 PHP <a class="header-anchor" href="#_3-1-測試-php" aria-label="Permalink to “3.1 測試 PHP”">​</a></h4>`,55)),p("p",null,[s[6]||(s[6]=a("打開 Web 瀏覽器，然後導航到 URL ",-1)),e(n,{href:"http://xn--IP-im8ckc/info.php"},{default:i(()=>[...s[5]||(s[5]=[a("http://IP地址/info.php",-1)])]),_:1}),s[7]||(s[7]=a("。",-1))]),s[25]||(s[25]=t(`<p>你就將看到 PHP 測試頁面。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/02/php-test-page.png" alt=""></p><p>通常，當用户向 Web 服務器發出請求時，Apache 首先會在文檔根目錄中查找名為 <code>index.html</code> 的文件。如果你想將 Apache 更改為 <code>php</code> 文件提供服務而不是其他文件，請將 <code>dir.conf</code> 配置文件中的 <code>index.php</code> 移至第一個位置，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/apache2/mods-enabled/dir.conf</span></span></code></pre></div><p>上面的配置文件（<code>dir.conf</code>） 內容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;IfModule mod_dir.c&gt;</span></span>
<span class="line"><span>DirectoryIndex index.html index.cgi index.pl index.php index.xhtml index.htm</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># vim: syntax=apache ts=4 sw=4 sts=4 sr noet</span></span></code></pre></div><p>將 <code>index.php</code> 移動到最前面。更改後，<code>dir.conf</code> 文件內容看起來如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;IfModule mod_dir.c&gt;</span></span>
<span class="line"><span>DirectoryIndex index.php index.html index.cgi index.pl index.xhtml index.htm</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># vim: syntax=apache ts=4 sw=4 sts=4 sr noet</span></span></code></pre></div><p>然後按下 <code>ESC</code> 鍵並且輸入 <code>:wq</code> 保存並關閉此文件。重新啓動 Apache 服務使更改生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart apache2</span></span></code></pre></div><h4 id="_3-2-安裝-php-模組" tabindex="-1">3.2 安裝 PHP 模組 <a class="header-anchor" href="#_3-2-安裝-php-模組" aria-label="Permalink to “3.2 安裝 PHP 模組”">​</a></h4><p>為了增加 PHP 的功能，可以安裝一些其他的 PHP 模組。</p><p>要列出可用的 PHP 模組，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-cache search php- | less</span></span></code></pre></div><p>輸出結果：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/06/php-modules.png" alt=""></p><p>使用方向鍵瀏覽結果。要退出，請輸入 <code>q</code> 並按下回車鍵。</p><p>要查找任意 <code>php</code> 模組的詳細信息，例如 <code>php-gd</code>，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-cache show php-gd</span></span></code></pre></div><p>安裝 PHP 模組請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install php-gd</span></span></code></pre></div><p>安裝所有的模組（雖然沒有必要），請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install php*</span></span></code></pre></div><p>安裝任何 <code>php</code> 模組後，請不要忘記重新啓動 Apache 服務。要檢查模組是否已加載，請在瀏覽器中打開 <code>info.php</code> 文件並檢查是否存在。</p><p>接下來，你可能需要安裝資料庫管理工具，以通過 Web 瀏覽器輕鬆管理資料庫。如果是這樣，請按照以下鏈接中的説明安裝 <code>phpMyAdmin</code>。</p><p>祝賀你！我們已經在 Ubuntu 服務器中成功配置了 LAMP 套件。</p><hr>`,27)),p("p",null,[s[9]||(s[9]=a("via: ",-1)),e(n,{href:"https://www.ostechnix.com/install-apache-mysql-php-lamp-stack-on-ubuntu-18-04-lts/"},{default:i(()=>[...s[8]||(s[8]=[a("https://www.ostechnix.com/install-apache-mysql-php-lamp-stack-on-ubuntu-18-04-lts/",-1)])]),_:1})]),p("p",null,[s[14]||(s[14]=a("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:i(()=>[...s[10]||(s[10]=[a("SK",-1)])]),_:1}),s[15]||(s[15]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[11]||(s[11]=[a("lujun9972",-1)])]),_:1}),s[16]||(s[16]=a(" 譯者：",-1)),e(n,{href:"https://github.com/stevenzdg988"},{default:i(()=>[...s[12]||(s[12]=[a("stevenzdg988",-1)])]),_:1}),s[17]||(s[17]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[20]||(s[20]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[19]||(s[19]=[a("Linux中國",-1)])]),_:1}),s[22]||(s[22]=a(" 榮譽推出",-1))])])}const P=l(c,[["render",r]]);export{v as __pageData,P as default};
